EQB(ROW(sub('f','1'),EQ,FRAC(N('12400'),V('π')),F('arctg'),D(N('0,94755')),EQ,FRAC(N('12400'),V('π')),MUL,N('0,75786'),O('≈'),N(ru(f1,2)),L(' Гц')))
P('Теперь подставим граничную частоту полосы задержания F<sub>3</sub> = 1440 Гц:')
